contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address target, address[] memory tos, uint v) public payable {
        bool reverted;
        try c.transfer(from, target, tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If transfer did not revert, every call it made to target must have succeeded,
        // which in particular requires tos to be non-empty and target to be a contract
        // that accepts the calls. If target rejects transfers, c.transfer must revert.
        bool completed = !reverted;
        bool targetRejects = target.code.length == 0;

        assert(!(completed && targetRejects));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address target, address[] memory tos, uint v) public payable {
        require(tos.length == 1, "exactly one destination");
        require(target != address(0), "target nonzero");

        bool reverted;
        bool ret;
        try c.transfer(from, target, tos, v) returns (bool r) {
            ret = r;
            reverted = false;
        } catch {
            ret = false;
            reverted = true;
        }

        // If the call completed, it must have returned true. If it reverted, no return is observable.
        assert(reverted || ret);
    }

    receive() external payable {}
}

